@startuml
class Customer {
  +address: string
  +vatNumber: string
  +headOfficeAddress: string
}

class Product {
  +stockLevel: int
}

class Order {
  +paymentDate: date
  +isPaid: boolean
}

class OrderLine {
  +quantity: int
  +isShipped: boolean
}

class Invoice {
}

class Shipment {
  +status: string
}

class DeliveryAddress {
  +address: string
}

Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives
Order "1" *-- "1..*" OrderLine : consists of
Order "1" -- "0..1" Invoice : has
Order "1" -- "*" Shipment : is split into
OrderLine "1" -- "0..*" Shipment : is part of
Shipment "1" -- "1" DeliveryAddress : delivered to
@enduml

